    {
      "dependency": "规范的时间适用、交易事实与合同法律状态共同影响请求的支持范围。",
      "basis": "dossier.md 导言、S01—S07、S12；rules.json 所附规范版本及效力条款。"
    },
    {
      "dependency": "交付、结算与付款记录的认定影响各项清算结果，各项结果共同支持整体财产审查。",
      "basis": "dossier.md S02—S09、S11—S12；rules.json 所附借款及清偿规范。"
    },
    {
      "dependency": "保证关系的法律状态、约定范围与行权事实共同决定即时给付请求能否成立及其范围。",
      "basis": "dossier.md S01、S06—S07、S10、S12；rules.json 所附保证规范。"
    }
  ],
